source = 'context_snapshot', guard = 'local'
@pytest.mark.parametrize("source", ["context_snapshot", "profile_metadata", "region_metadata"]) @pytest.mark.parametrize("guard", ["local", "constant"]) def test_same_context_source_owner_cannot_register_two_schemas_even_unused(source, guard): data, ctx, expr = setup() schema = deepcopy(ctx["context_registrations"][0]["schema_ref"]) if source == "profile_metadata": first = dict(source=source, schema_ref=schema, profile_ref=ctx["profile_ref"]) elif source == "region_metadata": first = deepcopy(ctx["context_registrations"][1]) else: first = deepcopy(ctx["context_registrations"][0]) second = deepcopy(first) second["schema_ref"]["artifact_id"] = "distinct-context-schema" descriptor = deepcopy(next(item for item in ctx["descriptors"] if item["schema_ref"] == first["schema_ref"])) descriptor["schema_ref"] = deepcopy(second["schema_ref"]) ctx["context_registrations"] = [first, second] ctx["descriptors"].append(descriptor) result = bind(data, ctx, expr if guard == "local" else True) > assert result.report.aggregate_status == "invalid" E AssertionError: assert 'deferred' == 'invalid' E E - invalid E + deferred
tests/negative/test_b_condition_bindings_invalid.py:269: AssertionError

